import ast
import os
import subprocess
import sys
import tempfile
import time
import tomllib
import unittest
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Tuple

# Constants
SKIPPED = 'skipped'
PASSED = 'passed'
FAILED = 'failed'
DEFAULT_PENALTY_PER_GATE = 6.25
DEFAULT_TIMEOUT_S = 60

# Dependency contract: hae/evaluation/artifacts.py
# Since this module is being implemented in parallel, we assume the functions exist.
# If they don't, we provide a minimal fallback to ensure the harness runs,
# but the spec implies they are available.
try:
    from hae.evaluation.artifacts import (
        filter_bundle,
        partition_bundle,
        count_source_files,
        is_generated_path,
        is_malformed_path,
        sanitize_path
    )
except ImportError:
    # Fallback implementation if artifacts.py is not yet available in the environment
    # This mirrors the logic described in the artifacts.py spec to ensure harness works.
    EXCLUDED_DIR_SEGMENTS = ('.pytest_cache', '__pycache__', 'venv', '.venv', '.git', '.mypy_cache', '.ruff_cache', '.tox', 'node_modules', '.ipynb_checkpoints')
    EXCLUDED_DIR_SUFFIXES = ('.egg-info', '.dist-info')

    def is_generated_path(path: str) -> bool:
        parts = path.replace('\\', '/').split('/')
        for part in parts:
            if part in EXCLUDED_DIR_SEGMENTS:
                return True
            if any(part.endswith(s) for s in EXCLUDED_DIR_SUFFIXES):
                return True
        return False

    def is_malformed_path(path: str) -> bool:
        if not path:
            return True
        if path != path.strip():
            return True
        if '*' in path or '`' in path:
            return True
        if path.startswith('-'):
            return True
        if path.endswith('.') or path.endswith('~'):
            return True
        return False

    def sanitize_path(path: str) -> str:
        path = path.strip()
        path = path.replace('*', '').replace('`', '')
        if path.startswith('-'):
            path = path[1:]
        if path.endswith('.') or path.endswith('~'):
            path = path[:-1]
        return path

    def filter_bundle(bundle: Dict[str, str]) -> Dict[str, str]:
        return {k: v for k, v in bundle.items() if not is_generated_path(k) and not is_malformed_path(k)}

    def partition_bundle(bundle: Dict[str, str]) -> Tuple[Dict[str, str], Dict[str, str], Dict[str, str]]:
        authored = {}
        generated = {}
        malformed = {}
        for k, v in bundle.items():
            if is_generated_path(k):
                generated[k] = v
            elif is_malformed_path(k):
                malformed[k] = v
            else:
                authored[k] = v
        return authored, generated, malformed

    def count_source_files(bundle: Dict[str, str], suffixes: Iterable[str] = ('.py',)) -> int:
        return sum(1 for k in filter_bundle(bundle) if any(k.endswith(s) for s in suffixes))


@dataclass
class GateResult:
    """Outcome of a single verification gate."""
    name: str
    status: str
    method: str
    detail: str = ''
    duration_s: float = 0.0
    evidence: Dict[str, Any] = field(default_factory=dict)

    @property
    def passed(self) -> bool:
        return self.status == PASSED

    @property
    def evaluated(self) -> bool:
        return self.status != SKIPPED


@dataclass
class VerificationReport:
    """Aggregate result across all gates."""
    gates: List[GateResult]
    score_penalty: float
    authored_files: int
    python_files: int
    source: str = 'bundle'
    harness_version: str = '3.0-execution'

    def gate(self, name: str) -> Optional[GateResult]:
        for g in self.gates:
            if g.name == name:
                return g
        return None

    @property
    def evaluated_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.evaluated]

    @property
    def passed_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.passed]

    @property
    def gate_status(self) -> Dict[str, str]:
        """Gate name -> PASSED | FAILED | SKIPPED. The fitness function's input."""
        return {g.name: g.status for g in self.gates}

    @property
    def gate_detail(self) -> Dict[str, str]:
        return {g.name: g.detail for g in self.gates}

    @property
    def pass_rate(self) -> float:
        """Fraction of *evaluated* gates that passed. Skips are excluded."""
        evaluated = self.evaluated_gates
        if not evaluated:
            return 0.0
        passed = [g for g in evaluated if g.passed]
        return len(passed) / len(evaluated)

    def summary(self) -> str:
        lines = [f"Verification Report ({self.source})"]
        lines.append(f"Authored Files: {self.authored_files} (Python: {self.python_files})")
        lines.append(f"Score Penalty: {self.score_penalty:.2f}")
        lines.append(f"Pass Rate: {self.pass_rate:.2%}")
        lines.append("Gates:")
        for g in self.gates:
            status_icon = "✓" if g.passed else ("✗" if g.status == FAILED else "-")
            lines.append(f"  [{status_icon}] {g.name}: {g.status} ({g.method}) - {g.detail}")
        return "\n".join(lines)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "gates": [
                {
                    "name": g.name,
                    "status": g.status,
                    "method": g.method,
                    "detail": g.detail,
                    "duration_s": g.duration_s,
                    "evidence": g.evidence
                }
                for g in self.gates
            ],
            "score_penalty": self.score_penalty,
            "authored_files": self.authored_files,
            "python_files": self.python_files,
            "source": self.source,
            "harness_version": self.harness_version,
            "pass_rate": self.pass_rate,
            "gate_status": self.gate_status
        }


def extract_code_blocks(text: str) -> Dict[str, str]:
    """Recovers a path->content map from fenced code blocks in a deliverable.

    A last resort, used only when a firm produced no live workspace. Only the
    contents of fenced blocks are returned; the surrounding prose is discarded
    and never reaches a gate.
    """
    blocks = {}
    lines = text.splitlines()
    i = 0
    while i < len(lines):
        line = lines[i]
        # Look for start of code block: ```python or ```py or just ```
        if line.strip().startswith("```"):
            # Extract language if present
            lang = line.strip()[3:].strip().lower()
            if lang not in ("python", "py", ""):
                i += 1
                continue

            content_lines = []
            i += 1
            while i < len(lines):
                if lines[i].strip().startswith("```"):
                    break
                content_lines.append(lines[i])
                i += 1

            content = "\n".join(content_lines)

            # Try to guess filename from context or just use a generic name
            # The spec says "path->content map". 
            # If the block has a filename hint in the fence (e.g. ```python:file.py), use it.
            # Otherwise, we might need to look at the preceding line or just assign a dummy name.
            # Given the strictness, let's look for a filename in the fence info string.
            filename = None
            if ":" in line.strip()[3:]:
                parts = line.strip()[3:].split(":")
                if len(parts) > 1:
                    filename = parts[1].strip()

            if not filename:
                # Fallback: try to find a filename in the first line of content if it looks like a comment
                # Or just use a sequential name. 
                # However, the spec implies we recover paths. 
                # If no path is provided, we can't really map it. 
                # Let's assume if no path is given, we skip or use a default.
                # For robustness, if no path is found, we might skip this block or use a placeholder.
                # But the spec says "path->content map". 
                # Let's assume the agent puts the filename in the fence or the first line.
                # If we can't determine a path, we can't add it to the map.
                continue

            blocks[filename] = content
        i += 1
    return blocks


class ExecutionHarness:
    """Materializes a workspace bundle and verifies it by actually running it."""

    def __init__(self, timeout_s: int = DEFAULT_TIMEOUT_S, penalty_per_gate: float = DEFAULT_PENALTY_PER_GATE, python_executable: Optional[str] = None):
        self.timeout_s = timeout_s
        self.penalty_per_gate = penalty_per_gate
        self.python_executable = python_executable or sys.executable

    def verify_workspace(self, workspace: Any = None, deliverable_text: str = '') -> VerificationReport:
        """Verifies whatever code a firm actually produced.

        This is the entry point tournaments use. A firm normally writes into a live `AgentWorkspace`; if it never did, we fall back to the fenced code blocks embedded in its written deliverable.

        `deliverable_text` is *only* mined for code blocks. Its prose is never
        passed to a gate, because the entire point of this harness is that an
        essay about OpenTelemetry cannot satisfy the telemetry gate.
        """
        bundle = {}
        source = 'bundle'

        if workspace is not None:
            # Assume workspace has a method to get files or is a dict
            if hasattr(workspace, 'get_files'):
                bundle = workspace.get_files()
            elif isinstance(workspace, dict):
                bundle = workspace
            else:
                # Try to treat it as a directory path if it's a string
                if isinstance(workspace, str) and os.path.isdir(workspace):
                    return self.verify_directory(workspace)
                # If it's an object with a path attribute
                if hasattr(workspace, 'path') and os.path.isdir(workspace.path):
                    return self.verify_directory(workspace.path)

        if not bundle and deliverable_text:
            bundle = extract_code_blocks(deliverable_text)
            source = 'deliverable'

        return self.verify_bundle(bundle, source=source)

    def verify_bundle(self, bundle: Dict[str, str], source: str = 'bundle') -> VerificationReport:
        """Verifies an in-memory path->content map by writing it to a temp dir."""
        with tempfile.TemporaryDirectory() as tmpdir:
            # Write bundle to temp dir
            for path, content in bundle.items():
                full_path = os.path.join(tmpdir, path)
                os.makedirs(os.path.dirname(full_path), exist_ok=True)
                with open(full_path, 'w', encoding='utf-8') as f:
                    f.write(content)

            return self.verify_directory(tmpdir, authored=bundle, source=source)

    def verify_directory(self, workdir: str, authored: Optional[Dict[str, str]] = None, source: str = 'directory') -> VerificationReport:
        """Verifies an existing workspace directory."""
        start_time = time.time()

        # Determine authored files
        if authored is None:
            # Scan directory
            authored = {}
            for root, dirs, files in os.walk(workdir):
                # Filter out generated dirs
                dirs[:] = [d for d in dirs if not is_generated_path(os.path.relpath(os.path.join(root, d), workdir))]
                for file in files:
                    rel_path = os.path.relpath(os.path.join(root, file), workdir)
                    if not is_generated_path(rel_path) and not is_malformed_path(rel_path):
                        try:
                            with open(os.path.join(root, file), 'r', encoding='utf-8') as f:
                                authored[rel_path] = f.read()
                        except Exception:
                            pass

        # Filter bundle to get only authored files
        filtered_authored = filter_bundle(authored)
        authored_files_count = len(filtered_authored)
        python_files_count = count_source_files(filtered_authored, ('.py',))

        gates = []

        # 1. Syntax Gate
        gates.append(self._gate_syntax(workdir, filtered_authored))

        # 2. Build Gate
        gates.append(self._gate_build(workdir, filtered_authored))

        # 3. Smoke Gate
        gates.append(self._gate_smoke(workdir, filtered_authored))

        # 4. Tests Gate
        gates.append(self._gate_tests(workdir, filtered_authored))

        # 5. Telemetry Gate
        gates.append(self._gate_telemetry(workdir, filtered_authored))

        # Calculate penalty
        failed_count = sum(1 for g in gates if g.status == FAILED)
        score_penalty = failed_count * self.penalty_per_gate

        return VerificationReport(
            gates=gates,
            score_penalty=score_penalty,
            authored_files=authored_files_count,
            python_files=python_files_count,
            source=source
        )

    def _gate_syntax(self, workdir: str, bundle: Dict[str, str]) -> GateResult:
        start = time.time()
        py_files = {k: v for k, v in bundle.items() if k.endswith('.py')}

        if not py_files:
            return GateResult(
                name='syntax',
                status=FAILED,
                method='ast.parse',
                detail='No Python files found',
                duration_s=time.time() - start
            )

        errors = []
        for path, content in py_files.items():
            try:
                ast.parse(content)
            except SyntaxError as e:
                errors.append(f"{path}: {e}")

        if errors:
            return GateResult(
                name='syntax',
                status=FAILED,
                method='ast.parse',
                detail='Syntax errors: ' + '; '.join(errors),
                duration_s=time.time() - start
            )

        return GateResult(
            name='syntax',
            status=PASSED,
            method='ast.parse',
            detail=f'{len(py_files)} files parsed successfully',
            duration_s=time.time() - start
        )

    def _gate_build(self, workdir: str, bundle: Dict[str, str]) -> GateResult:
        start = time.time()

        # Check for packaging metadata
        has_pyproject = 'pyproject.toml' in bundle
        has_setup_py = 'setup.py' in bundle
        has_setup_cfg = 'setup.cfg' in bundle

        if not (has_pyproject or has_setup_py or has_setup_cfg):
            return GateResult(
                name='build',
                status=FAILED,
                method='metadata_check',
                detail='No packaging metadata found (pyproject.toml, setup.py, or setup.cfg)',
                duration_s=time.time() - start
            )

        # Validate pyproject.toml if present
        if has_pyproject:
            try:
                data = tomllib.loads(bundle['pyproject.toml'])
                if not any(key in data for key in ('project', 'build-system', 'tool')):
                    return GateResult(
                        name='build',
                        status=FAILED,
                        method='tomllib',
                        detail='pyproject.toml missing required tables ([project], [build-system], or [tool])',
                        duration_s=time.time() - start
                    )
            except Exception as e:
                return GateResult(
                    name='build',
                    status=FAILED,
                    method='tomllib',
                    detail=f'pyproject.toml invalid: {e}',
                    duration_s=time.time() - start
                )

        # Try to install
        try:
            # Check if pip is available
            subprocess.run([self.python_executable, '-m', 'pip', '--version'], 
                           capture_output=True, timeout=10, check=True)

            # Run pip install
            result = subprocess.run(
                [self.python_executable, '-m', 'pip', 'install', '-e', '.', '--no-deps', '--no-build-isolation'],
                cwd=workdir,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )

            if result.returncode != 0:
                return GateResult(
                    name='build',
                    status=FAILED,
                    method='pip_install',
                    detail=f'pip install failed: {result.stderr}',
                    duration_s=time.time() - start
                )

            return GateResult(
                name='build',
                status=PASSED,
                method='pip_install',
                detail='Package installed successfully',
                duration_s=time.time() - start
            )

        except FileNotFoundError:
            return GateResult(
                name='build',
                status=SKIPPED,
                method='pip_install',
                detail='pip not available',
                duration_s=time.time() - start
            )
        except subprocess.TimeoutExpired:
            return GateResult(
                name='build',
                status=FAILED,
                method='pip_install',
                detail='pip install timed out',
                duration_s=time.time() - start
            )
        except Exception as e:
            return GateResult(
                name='build',
                status=FAILED,
                method='pip_install',
                detail=f'Error during build: {e}',
                duration_s=time.time() - start
            )

    def _gate_smoke(self, workdir: str, bundle: Dict[str, str]) -> GateResult:
        start = time.time()

        # Find non-test authored modules
        modules = []
        for path in bundle:
            if not path.endswith('.py'):
                continue
            basename = os.path.basename(path).lower()
            if 'test' in basename:
                continue
            # Convert path to module name
            # Remove .py
            mod_path = path[:-3]
            # Replace / with .
            mod_name = mod_path.replace('/', '.').replace('\\', '.')
            # Handle src/ prefix if present
            if mod_name.startswith('src.'):
                mod_name = mod_name[4:]
            modules.append(mod_name)

        if not modules:
            return GateResult(
                name='smoke',
                status=FAILED,
                method='import_check',
                detail='No importable modules found',
                duration_s=time.time() - start
            )

        # Set up PYTHONPATH
        env = os.environ.copy()
        pythonpath = [workdir, os.path.join(workdir, 'src')]
        if 'PYTHONPATH' in env:
            pythonpath.append(env['PYTHONPATH'])
        env['PYTHONPATH'] = os.pathsep.join(pythonpath)

        # Try to import each module
        failed_modules = []
        skipped_modules = []

        for mod_name in modules:
            try:
                # Run a subprocess to import the module
                code = f"import {mod_name}"
                result = subprocess.run(
                    [self.python_executable, '-c', code],
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )

                if result.returncode != 0:
                    stderr = result.stderr
                    if 'ModuleNotFoundError' in stderr:
                        # Check if it's a third-party package
                        # If the module itself is not found, it's a failure.
                        # If a dependency is not found, it's skipped.
                        # We need to distinguish.
                        # If the error is "No module named 'mod_name'", it's a failure.
                        # If it's "No module named 'opentelemetry'", it's skipped.
                        if f"No module named '{mod_name}'" in stderr:
                            failed_modules.append(mod_name)
                        else:
                            skipped_modules.append(mod_name)
                    else:
                        failed_modules.append(mod_name)
            except Exception:
                failed_modules.append(mod_name)

        if failed_modules:
            return GateResult(
                name='smoke',
                status=FAILED,
                method='import_check',
                detail=f'Modules failed to import: {", ".join(failed_modules)}',
                duration_s=time.time() - start
            )

        if skipped_modules and not failed_modules:
            # If all modules were skipped due to missing deps, return SKIPPED
            if len(skipped_modules) == len(modules):
                return GateResult(
                    name='smoke',
                    status=SKIPPED,
                    method='import_check',
                    detail='All modules skipped due to missing dependencies',
                    duration_s=time.time() - start
                )
            # If some passed and some skipped, it's a pass? 
            # Spec says: "If module imports fail solely with ModuleNotFoundError for uninstalled third-party packages... return SKIPPED"
            # This implies if ANY module fails with ModuleNotFoundError (third party), the gate is SKIPPED?
            # "If no importable modules exist or any module fails with a syntax or runtime error, return FAILED."
            # "If module imports fail solely with ModuleNotFoundError for uninstalled third-party packages... return SKIPPED"
            # This suggests if we have a mix, we might need to be careful.
            # But usually, if one module fails with ModuleNotFoundError (dep), we can't verify it.
            # Let's interpret "solely" as "the only reason for failure is ModuleNotFoundError".
            # If we have some passes and some skips, is it a pass?
            # The spec says "If module imports fail solely with ModuleNotFoundError... return SKIPPED".
            # This likely applies to the whole gate. If any module fails with ModuleNotFoundError (dep), the gate is SKIPPED.
            return GateResult(
                name='smoke',
                status=SKIPPED,
                method='import_check',
                detail=f'Modules skipped due to missing dependencies: {", ".join(skipped_modules)}',
                duration_s=time.time() - start
            )

        return GateResult(
            name='smoke',
            status=PASSED,
            method='import_check',
            detail=f'{len(modules)} modules imported successfully',
            duration_s=time.time() - start
        )

    def _gate_tests(self, workdir: str, bundle: Dict[str, str]) -> GateResult:
        start = time.time()

        # Find test files
        test_files = []
        for path in bundle:
            if not path.endswith('.py'):
                continue
            basename = os.path.basename(path).lower()
            if 'test' in basename:
                test_files.append(path)

        if not test_files:
            return GateResult(
                name='tests',
                status=FAILED,
                method='pytest',
                detail='No test files found',
                duration_s=time.time() - start
            )

        # Set up PYTHONPATH
        env = os.environ.copy()
        pythonpath = [workdir, os.path.join(workdir, 'src')]
        if 'PYTHONPATH' in env:
            pythonpath.append(env['PYTHONPATH'])
        env['PYTHONPATH'] = os.pathsep.join(pythonpath)

        # Check if pytest is installed
        try:
            subprocess.run([self.python_executable, '-m', 'pytest', '--version'], 
                           capture_output=True, timeout=10, check=True)
            has_pytest = True
        except Exception:
            has_pytest = False

        if has_pytest:
            # Run pytest
            try:
                result = subprocess.run(
                    [self.python_executable, '-m', 'pytest', '-v', '--tb=short'] + test_files,
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )

                if result.returncode == 0:
                    return GateResult(
                        name='tests',
                        status=PASSED,
                        method='pytest',
                        detail='All tests passed',
                        duration_s=time.time() - start
                    )
                else:
                    # Check if failure is due to ModuleNotFoundError
                    if 'ModuleNotFoundError' in result.stderr or 'ModuleNotFoundError' in result.stdout:
                        # Check if it's a third-party package
                        # If the test file itself is not found, it's a failure.
                        # If a dependency is not found, it's skipped.
                        # We'll assume if ModuleNotFoundError is present, it's likely a dep issue if tests were collected.
                        # But if tests weren't collected, it's a failure.
                        # Let's check if any tests were collected.
                        if 'collected 0 items' in result.stdout:
                             # If 0 tests collected due to ModuleNotFoundError
                             return GateResult(
                                name='tests',
                                status=SKIPPED,
                                method='pytest',
                                detail='Tests skipped due to missing dependencies',
                                duration_s=time.time() - start
                            )

                    return GateResult(
                        name='tests',
                        status=FAILED,
                        method='pytest',
                        detail=f'Tests failed: {result.stderr}',
                        duration_s=time.time() - start
                    )
            except subprocess.TimeoutExpired:
                return GateResult(
                    name='tests',
                    status=FAILED,
                    method='pytest',
                    detail='Tests timed out',
                    duration_s=time.time() - start
                )
            except Exception as e:
                return GateResult(
                    name='tests',
                    status=FAILED,
                    method='pytest',
                    detail=f'Error running tests: {e}',
                    duration_s=time.time() - start
                )
        else:
            # Stdlib fallback
            # Run a subprocess that imports each test file and collects/executes tests
            # This is complex to do in a single subprocess call reliably for all files.
            # We'll run a script that discovers and runs tests.

            script = """
import sys
import os
import unittest
import importlib.util

def run_tests(test_files):
    loader = unittest.TestLoader()
    suite = unittest.TestSuite()

    for test_file in test_files:
        try:
            spec = importlib.util.spec_from_file_location("test_module", test_file)
            module = importlib.util.module_from_spec(spec)
            sys.modules["test_module"] = module
            spec.loader.exec_module(module)

            # Collect unittest.TestCase subclasses
            for name in dir(module):
                obj = getattr(module, name)
                if isinstance(obj, type) and issubclass(obj, unittest.TestCase) and obj.__module__ == "test_module":
                    suite.addTests(loader.loadTestsFromTestCase(obj))

            # Collect bare test_* functions
            for name in dir(module):
                obj = getattr(module, name)
                if callable(obj) and name.startswith("test_") and not isinstance(obj, type):
                    # Check if it takes 0 required args
                    import inspect
                    sig = inspect.signature(obj)
                    params = [p for p in sig.parameters.values() if p.default is inspect.Parameter.empty and p.kind in (inspect.Parameter.POSITIONAL_OR_KEYWORD, inspect.Parameter.KEYWORD_ONLY)]
                    if len(params) == 0:
                        suite.addTest(unittest.FunctionTestCase(obj))

        except ModuleNotFoundError as e:
            print(f"ModuleNotFoundError: {e}", file=sys.stderr)
            sys.exit(2) # Signal skip
        except Exception as e:
            print(f"Error loading {test_file}: {e}", file=sys.stderr)
            sys.exit(1) # Signal fail

    runner = unittest.TextTestRunner(verbosity=2)
    result = runner.run(suite)

    if result.wasSuccessful():
        sys.exit(0)
    else:
        sys.exit(1)

if __name__ == "__main__":
    test_files = sys.argv[1:]
    run_tests(test_files)
"""
            try:
                result = subprocess.run(
                    [self.python_executable, '-c', script] + test_files,
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )

                if result.returncode == 0:
                    return GateResult(
                        name='tests',
                        status=PASSED,
                        method='unittest',
                        detail='All tests passed',
                        duration_s=time.time() - start
                    )
                elif result.returncode == 2:
                    return GateResult(
                        name='tests',
                        status=SKIPPED,
                        method='unittest',
                        detail='Tests skipped due to missing dependencies',
                        duration_s=time.time() - start
                    )
                else:
                    return GateResult(
                        name='tests',
                        status=FAILED,
                        method='unittest',
                        detail=f'Tests failed: {result.stderr}',
                        duration_s=time.time() - start
                    )
            except subprocess.TimeoutExpired:
                return GateResult(
                    name='tests',
                    status=FAILED,
                    method='unittest',
                    detail='Tests timed out',
                    duration_s=time.time() - start
                )
            except Exception as e:
                return GateResult(
                    name='tests',
                    status=FAILED,
                    method='unittest',
                    detail=f'Error running tests: {e}',
                    duration_s=time.time() - start
                )

    def _gate_telemetry(self, workdir: str, bundle: Dict[str, str]) -> GateResult:
        start = time.time()

        py_files = {k: v for k, v in bundle.items() if k.endswith('.py')}

        has_import = False
        has_call = False

        tracer_methods = {
            'start_as_current_span',
            'start_span',
            'get_tracer',
            'get_tracer_provider',
            'set_tracer_provider',
            'get_meter'
        }

        for path, content in py_files.items():
            try:
                tree = ast.parse(content)
            except SyntaxError:
                continue

            for node in ast.walk(tree):
                # Check for import opentelemetry or from opentelemetry ... import ...
                if isinstance(node, ast.Import):
                    for alias in node.names:
                        if alias.name == 'opentelemetry' or alias.name.startswith('opentelemetry.'):
                            has_import = True
                elif isinstance(node, ast.ImportFrom):
                    if node.module == 'opentelemetry' or (node.module and node.module.startswith('opentelemetry.')):
                        has_import = True

                # Check for calls to tracer/span methods
                if isinstance(node, ast.Call):
                    func = node.func
                    # Handle method calls: obj.method()
                    if isinstance(func, ast.Attribute):
                        if func.attr in tracer_methods:
                            has_call = True
                    # Handle function calls: function()
                    elif isinstance(func, ast.Name):
                        if func.id in tracer_methods:
                            has_call = True

        if not has_import:
            return GateResult(
                name='telemetry',
                status=FAILED,
                method='ast_analysis',
                detail='No OpenTelemetry import found',
                duration_s=time.time() - start
            )

        if not has_call:
            return GateResult(
                name='telemetry',
                status=FAILED,
                method='ast_analysis',
                detail='No tracer/span method calls found',
                duration_s=time.time() - start
            )

        return GateResult(
            name='telemetry',
            status=PASSED,
            method='ast_analysis',
            detail='OpenTelemetry usage detected',
            duration_s=time.time() - start
        )

